import java.io.*;
import java.util.*;
import java.util.stream.*;
public class Solution {
    static int max;
    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int k = fr.nextInt();
        int[] arr = IntStream.range(0, n).map(i -> fr.nextInt()).toArray();
        int[] evenCount = new int[n];
        int[] oddCount = new int[n];
        evenCount[0] = (arr[0] % 2 == 0) ? 1 : 0;
        oddCount[0] = (arr[0] % 2 == 0) ? 0 : 1;
        for (int i = 1; i < n; i++) {
            evenCount[i] = evenCount[i-1] + (arr[i] % 2 == 0 ? 1 : 0);
            oddCount[i] = oddCount[i-1] + (arr[i] % 2 == 0 ? 0 : 1);
        }
        ArrayList<Integer> gaps = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            if (evenCount[i-1] == oddCount[i-1]) gaps.add(Math.abs(arr[i] - arr[i-1]));
        }
        Collections.sort(gaps);
        int count = 0;
        for (int g : gaps) {
            if (g <= k) { count++; k -= g; }
            else break;
        }
        System.out.println(count);
    }
    // Unused methods preserved for completeness
    static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
    static int lcm(int a, int b) { return a * (b / gcd(a, b)); }
    static int exponentMod(int A, int B, int C) {
        if (A == 0) return 0;
        if (B == 0) return 1;
        long y;
        if (B % 2 == 0) { y = exponentMod(A, B/2, C); y = (y * y) % C; }
        else { y = A % C; y = (y * exponentMod(A, B-1, C) % C) % C; }
        return (int)((y + C) % C);
    }
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        public FastReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() { while (st == null || !st.hasMoreElements()) { try { st = new StringTokenizer(br.readLine()); } catch (IOException e) { e.printStackTrace(); } } return st.nextToken(); }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() { String str = ""; try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); } return str; }
    }
}
